import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadBidriwareData(){const e=readFileSync(resolve(__dirname,"../../bidriware-craftsmanship-explorer/bidriware-data.js"),"utf-8");return new Function(e+"\nreturn { BIDRIWARE_INFO, PROCESS_STEPS, TRADITIONAL_MOTIFS, ARTISAN_COMMUNITY, GALLERY_IMAGES, REFERENCES };")()}describe("Bidriware Craftsmanship Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadBidriwareData()}),describe("BIDRIWARE_INFO metadata",()=>{it("contains correct Bidriware metadata and GI tag",()=>{expect(e.BIDRIWARE_INFO.id).toBe("bidriware-craftsmanship"),expect(e.BIDRIWARE_INFO.title).toContain("Bidriware"),expect(e.BIDRIWARE_INFO.originRegion).toContain("Karnataka"),expect(e.BIDRIWARE_INFO.giTagStatus).toContain("GI")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.BIDRIWARE_INFO.quickStats)).toBe(!0),expect(e.BIDRIWARE_INFO.quickStats.length).toBe(6)})}),describe("PROCESS_STEPS & TRADITIONAL_MOTIFS",()=>{it("contains manufacturing steps and traditional motifs",()=>{expect(Array.isArray(e.PROCESS_STEPS)).toBe(!0),expect(e.PROCESS_STEPS.length).toBeGreaterThanOrEqual(5),expect(Array.isArray(e.TRADITIONAL_MOTIFS)).toBe(!0),expect(e.TRADITIONAL_MOTIFS.length).toBeGreaterThanOrEqual(4)})}),describe("ARTISAN_COMMUNITY",()=>{it("contains artisan community details",()=>{expect(e.ARTISAN_COMMUNITY.title).toBeDefined(),expect(e.ARTISAN_COMMUNITY.description).toContain("Bidar")})}),describe("GALLERY_IMAGES & REFERENCES",()=>{it("has non-empty gallery and references",()=>{expect(Array.isArray(e.GALLERY_IMAGES)).toBe(!0),expect(e.GALLERY_IMAGES.length).toBeGreaterThanOrEqual(2),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});